/**
 * 每次循环使用两次比较以执行标准的折半查找.
 * 找到时返回所求项的下标，找不到则返回-1.
 */
template <typename Comparable>
int binarySearch( const vector<Comparable> & a, const Comparable & x )
{
    int low = 0, high = a.size( ) - 1;

    while( low <= high )
    {
        int mid = ( low + high ) / 2;

        if( a[ mid ] < x )
            low = mid + 1;
        else if( a[ mid ] > x )
            high = mid - 1;
        else
            return mid;   // 已找到
    }
    return NOT_FOUND;     // NOT_FOUND 被定义为-1
}

